350    inline hb_blob_t *sanitize_blob (hb_blob_t *blob)
   351    {
   352      bool sane;
   353
   354      init (blob);
   355
   356    retry:
   357      DEBUG_MSG_FUNC (SANITIZE, start, "start");
   358
   359      start_processing ();
   360
   361      if (unlikely (!start))
   362      {
   363        end_processing ();
   364        return blob;
   365      }
   366
   367      Type *t = CastP<Type> (const_cast<char *> (start));
   368
   369      sane = t->sanitize (this);
   370      if (sane)
   371      {
   372        if (edit_count)
   373        {
   374          DEBUG_MSG_FUNC (SANITIZE, start, "passed first round with %d edits; going for second round", edit_count);
   375
   376          /* sanitize again to ensure no toe-stepping */
   377          edit_count = 0;
   378          sane = t->sanitize (this);
   379          if (edit_count) {
   380            DEBUG_MSG_FUNC (SANITIZE, start, "requested %d edits in second round; FAILLING", edit_count);
   381            sane = false;
   382          }
   383        }
   384      }
   385      else
   386      {
   387        if (edit_count && !writable) {
   388          start = hb_blob_get_data_writable (blob, nullptr);
   389          end = start + blob->length;
   390
   391          if (start)
   392          {
   393            writable = true;
   394            /* ok, we made it writable by relocating.  try again */
   395            DEBUG_MSG_FUNC (SANITIZE, start, "retry");
   396            goto retry;
   397          }
   398        }
   399      }
